Imagine you have a Writable stream which needs to make a final commit or somehow confirm the data it received before the consumer can assume the stream has really finished:

``` javascript
'use strict';

var util = require('util');
var stream = require('stream');

var TestWriteStream = function(_path, options) {
    stream.Writable.call(this, options);
    this.once('finish', this.close);
};

util.inherits(TestWriteStream, stream.Writable);

TestWriteStream.prototype.close = function() {
    // any async commit/flush functionality here
    setTimeout(function () {
        console.log('Commit on close');
    }, 100);
};

TestWriteStream.prototype._write = function(chunk, encoding, callback) {
    callback();
};

var wStream = new TestWriteStream();

wStream.on('finish', process.exit);

wStream.write('data');
wStream.end();
```

In this particular example the message 'Commit on close' will never be displayed. Of course process.exit or setTimeout are only for example purposes here. But there is a problem - a consumer can never know that the stream has really finished.

