// 0.12.13: ~3.8
// 4.4.4: ~1.38
// 5.11.0: ~1.44
// 6.1.0: ~8.25
function map(cb, obj) {
    var res = new Array(this.length);
    if (obj) {
        for (var i = 0; i < this.length; i++) {
            res[i] = cb.call(obj, this[i], i);
        }
    } else {
        for (var i = 0; i < this.length; i++) {
            res[i] = cb(this[i], i);
        }
    }
